#include <iostream>
#include <string>
#include <vector>

struct Capacidad {
    int unidades;
};

struct Ocupacion {
    int unidades;
};

struct ReservaInvalida {};

class Reserva {
public:
    Reserva(Capacidad capacidad, Ocupacion ocupacion)
        : capacidad_{capacidad.unidades}, ocupacion_{ocupacion.unidades} {
        if (capacidad_ < 1 || capacidad_ > 20 || ocupacion_ < 0 || ocupacion_ > capacidad_) {
            throw ReservaInvalida{};
        }
    }

    int capacidad() const {
        return capacidad_;
    }

    int ocupacion() const {
        return ocupacion_;
    }

    int disponibles() const {
        return capacidad_ - ocupacion_;
    }

private:
    int capacidad_;
    int ocupacion_;
};

int main() {
    Reserva sala{Capacidad{8}, Ocupacion{3}};

    std::cout << sala.capacidad() << ":" << sala.ocupacion()
              << ":" << sala.disponibles();

    return 0;
}

